issue_context.body:
**Is your feature request related to a problem? Please describe.**

Having

~~~
mkdir -p 1/{bin,app}
cp /usr/sbin/busybox 1/bin/sh
cp /usr/sbin/busybox 1/app/env
~~~

It's not possible to run `/app/env` directly using systemd-run:

~~~
$ sudo systemd-run -G --wait --pipe -p RootDirectory=`pwd`/1 -p MountAPIVFS=true /app/env
Failed to find executable /app/env: No such file or directory
~~~

for I don't have `/app/env` on my host--such an executable exists only inside a "container".

Of course I can pass `/bin/sh -c /app/env`, but this requires having sh inside the "container".

**Describe the solution you'd like**
I patched systemd-run not to check for host executables if user sets `RootDirectory=` prop, but I'm not sure I'm not missing something:

~~~
diff --git a/src/run/run.c b/src/run/run.c
index 68a3750390..00eb426fea 100644
--- a/src/run/run.c
+++ b/src/run/run.c
@@ -66,6 +66,7 @@ static bool arg_aggressive_gc = false;
 static char *arg_working_directory = NULL;
 static bool arg_shell = false;
 static char **arg_cmdline = NULL;
+static bool host_cmd_check = true;

 STATIC_DESTRUCTOR_REGISTER(arg_environment, strv_freep);
 STATIC_DESTRUCTOR_REGISTER(arg_property, strv_freep);
@@ -319,6 +320,8 @@ static int parse_argv(int argc, char *argv[]) {
                 case 'p':
                         if (strv_extend(&arg_property, optarg) < 0)
                                 return log_oom();
+                        if (STARTSWITH_SET(optarg, "RootDirectory=", "RootImage="))
+                                host_cmd_check = false;

                         break;

@@ -1665,9 +1668,13 @@ static int run(int argc, char* argv[]) {

                 /* Patch in an absolute path */

-                r = find_binary(arg_cmdline[0], &command);
-                if (r < 0)
+                if (host_cmd_check) {
+                        r = find_binary(arg_cmdline[0], &command);
+                        if (r < 0)
                         return log_error_errno(r, "Failed to find executable %s: %m", arg_cmdline[0]);
+                } else {
+                        command = strdup(arg_cmdline[0]);
+                }

                 free_and_replace(arg_cmdline[0], command);
         }

~~~

